$nodeScript = @'
const fs = require('fs')
const { PNG } = require('pngjs')
const pixelmatch = require('pixelmatch')
const reference = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'))
const candidates = [
  ['401px', 'C:/Users/Administrator/.dsh/attachments/v1/objects/1c/1cc3434277a7fd19841c4f1b0ac00427e2cc64b14a3b3dc41d5c6b1aa20b58af'],
  ['442px', 'C:/Users/Administrator/.dsh/attachments/v1/objects/05/05f2d8550e77ca0c89d434a0939b285dfdce5fe11b443bb92d021172909e245c']
]
function crop(img, x, y, width, height) {
  const data = Buffer.alloc(width * height * 4)
  for (let row = 0; row < height; row++) img.data.copy(data, row * width * 4, ((y + row) * img.width + x) * 4, ((y + row) * img.width + x + width) * 4)
  return data
}
for (const [label, path] of candidates) {
  const actual = PNG.sync.read(fs.readFileSync(path))
  for (const [region, x0, x1] of [['active+first', 400, 680], ['nav-group', 400, 1680]]) {
    let best = null
    for (let shift = -60; shift <= 60; shift++) {
      const width = x1 - x0 - Math.abs(shift)
      const actualX = shift < 0 ? x0 - shift : x0
      const referenceX = shift > 0 ? x0 + shift : x0
      const a = crop(actual, actualX, 0, width, 110)
      const b = crop(reference, referenceX, 0, width, 110)
      const mismatched = pixelmatch(a, b, null, width, 110, { threshold: 0.1, includeAA: false })
      const rate = mismatched / (width * 110)
      if (!best || rate < best.rate) best = { shift, rate }
    }
    console.log(`${label} ${region}: bestShift=${best.shift}px, mismatch=${(best.rate * 100).toFixed(3)}%`)
  }
}
'@
node -e $nodeScript
